CREATE DATABASE IF NOT EXISTS janani;
USE janani;

CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, mobile VARCHAR(20), date_of_birth DATE, emergency_contact VARCHAR(120), pregnancy_status ENUM('pregnant','postpartum','trying','not_pregnant') DEFAULT 'not_pregnant', role ENUM('user','admin') DEFAULT 'user', is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE pregnancy_details (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL UNIQUE, lmp_date DATE, due_date DATE, doctor_name VARCHAR(150), current_information TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE pregnancy_week_content (id INT PRIMARY KEY AUTO_INCREMENT, week_number TINYINT NOT NULL UNIQUE, baby_development TEXT, maternal_changes TEXT, nutrition_guidance TEXT, wellness_guidance TEXT, routine_note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE appointments (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, provider_name VARCHAR(150) NOT NULL, appointment_date DATETIME NOT NULL, notes TEXT, status ENUM('upcoming','completed','cancelled') DEFAULT 'upcoming', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_appointments_user_date (user_id, appointment_date));
CREATE TABLE vaccination_reminders (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT, reminder_date DATE NOT NULL, reminder_time TIME, reminder_type VARCHAR(60) DEFAULT 'vaccination', status ENUM('pending','completed') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE health_content (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, category VARCHAR(80) NOT NULL, summary TEXT, body TEXT NOT NULL, published BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE government_schemes (id INT PRIMARY KEY AUTO_INCREMENT, scheme_name VARCHAR(180) NOT NULL, description TEXT NOT NULL, eligibility TEXT, benefits TEXT, required_documents TEXT, application_info TEXT, official_url VARCHAR(500), is_demo BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE menstrual_cycles (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, cycle_start_date DATE NOT NULL, cycle_length SMALLINT DEFAULT 28, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE chat_messages (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, sender ENUM('user','assistant') NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE faq (id INT PRIMARY KEY AUTO_INCREMENT, question TEXT NOT NULL, answer TEXT NOT NULL, category VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE admin_users (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL UNIQUE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
